using System.Security.Claims;
using BARANG.Backoffice.Components;

namespace BARANG.Backoffice.Tests;

public sealed class BackofficeModuleTests
{
    [Fact] public void EveryCompletedModuleHasUniquePermissionAndCoreReadRoute(){Assert.Equal(14,ModuleCatalog.All.Count);Assert.Equal(14,ModuleCatalog.All.Select(x=>x.Code).Distinct().Count());Assert.All(ModuleCatalog.All,x=>{Assert.StartsWith("api/v1/",x.ReadPath);Assert.Contains('.',x.Permission);});}
    [Fact] public void NavigationUsesRealPermissionClaims(){var orders=ModuleCatalog.All.Single(x=>x.Code=="orders");var allowed=new ClaimsPrincipal(new ClaimsIdentity([new Claim("barang:permission","order.read")],"test"));var denied=new ClaimsPrincipal(new ClaimsIdentity([],"test"));Assert.True(ModuleCatalog.IsVisible(orders,allowed));Assert.False(ModuleCatalog.IsVisible(orders,denied));}
    [Fact] public void SystemAdministratorCanReachAllModules(){var admin=new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.Role,"system.administrator")],"test"));Assert.All(ModuleCatalog.All,x=>Assert.True(ModuleCatalog.IsVisible(x,admin)));}
    [Fact] public void NavigationExposesDocumentDrivenOperationalAreas(){var admin=new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.Role,"system.administrator")],"test"));Assert.True(ModuleCatalog.Navigation.Count>=10);var direct=ModuleCatalog.Navigation.Where(x=>x.Route is not null).Select(x=>new BackofficeNavigationItem(x.LabelKey,x.Route!,x.Permission!)).ToArray();var items=direct.Concat(ModuleCatalog.Navigation.SelectMany(x=>x.Items).SelectMany(x=>x.Children is {Count:>0}?x.Children:new[]{x})).ToArray();Assert.DoesNotContain(items,x=>x.Route=="/workspace/reports");Assert.Contains(items,x=>x.Route=="/workspace/notifications");Assert.Contains(items,x=>x.Route=="/workspace/management");Assert.Equal("Nav_Orders",ModuleCatalog.Navigation[4].LabelKey);Assert.Equal("Nav_Cartable",ModuleCatalog.Navigation[5].LabelKey);Assert.Equal("Nav_Notifications",ModuleCatalog.Navigation[^2].LabelKey);Assert.Equal("Nav_ManagementDashboard",ModuleCatalog.Navigation[^1].LabelKey);Assert.All(items,x=>{Assert.StartsWith("/",x.Route);Assert.True(ModuleCatalog.IsVisible(x,admin));});}
    [Fact] public void OrganizationalModelUsesIntegratedInventoryPurchasingWorkspace(){var master=ModuleCatalog.Navigation.Single(x=>x.LabelKey=="Nav_MasterData");Assert.Equal(12,master.Items.Count);var pricing=ModuleCatalog.Navigation.Single(x=>x.LabelKey=="Nav_Pricing");Assert.Equal("/workspace/pricing",pricing.Route);Assert.Empty(pricing.Items);var inventory=ModuleCatalog.Navigation.Single(x=>x.LabelKey=="Nav_InventoryPurchasing");Assert.Equal("/workspace/inventory",inventory.Route);Assert.Empty(inventory.Items);Assert.DoesNotContain(ModuleCatalog.Navigation.SelectMany(x=>x.Items),x=>x.Route is "/admin/warehouses" or "/inventory/shortages" or "/workspace/purchasing");}
    [Fact] public void SupplierReferencesAreOneDirectMasterDataDestinationWithLookupPermission(){var master=ModuleCatalog.Navigation.Single(x=>x.LabelKey=="Nav_MasterData");var item=Assert.Single(master.Items,x=>x.Route=="/master/reference-data/suppliers");Assert.Equal("lookup.read",item.Permission);Assert.Null(item.Children);Assert.True(ModuleCatalog.IsVisible(item,new ClaimsPrincipal(new ClaimsIdentity([new Claim("barang:permission","lookup.read")],"test"))));}
    [Fact] public void UserAccessManagementIsOneDirectNavigationDestination(){var item=ModuleCatalog.Navigation.SelectMany(x=>x.Items).Single(x=>x.LabelKey=="Nav_UserAccessManagement");Assert.Null(item.Children);Assert.Equal("/admin/user-access",item.Route);Assert.Equal("security.user.read",item.Permission);}
    [Fact] public void FoundationSelectorsAndGridUseSharedInteractivePatterns(){string root=FindRepositoryRoot();string page=File.ReadAllText(Path.Combine(root,"01_CORE","src","BARANG.Backoffice","Components","Pages","AdminEntityManager.razor"));string select=File.ReadAllText(Path.Combine(root,"01_CORE","src","BARANG.Backoffice","Components","SearchableSelect.razor"));Assert.Contains("<SearchableSelect",page);Assert.DoesNotContain("<select",page,StringComparison.OrdinalIgnoreCase);Assert.Contains("@oninput=\"Filter\"",select);Assert.Contains("ArrowDown",select);Assert.Contains("NoOptions",select);Assert.Contains("Paged",page);Assert.Contains("SortBy",page);Assert.Contains("Busy",page);}
    [Fact] public void ObsoleteCombinedFinanceNavigationIsRemovedWhileValidFinanceRouteRemains(){Assert.DoesNotContain(ModuleCatalog.Navigation,x=>x.LabelKey=="Nav_Finance");Assert.DoesNotContain(ModuleCatalog.Navigation.SelectMany(x=>x.Items),x=>x.LabelKey=="Nav_Finance"||x.Route=="/workspace/finance");Assert.Single(ModuleCatalog.Navigation,x=>x.LabelKey=="Nav_Pricing"&&x.Route=="/workspace/pricing");string root=FindRepositoryRoot();string financePage=File.ReadAllText(Path.Combine(root,"01_CORE","src","BARANG.Backoffice","Components","Pages","FinanceWorkspace.razor"));Assert.Contains("@page \"/finance/{OrderId:guid}\"",financePage);string financeApi=File.ReadAllText(Path.Combine(root,"01_CORE","src","BARANG.Core.Api","Finance","FinanceEndpoints.cs"));Assert.Contains("MapGroup(\"/api/v1/orders/{orderId:guid}/finance\")",financeApi);Assert.Contains("PaymentManage",financeApi);Assert.Contains("InvoiceManage",financeApi);}
    [Fact] public void OrderWizardStepperMatchesBusinessContentAndPriorityLocalization(){string root=FindRepositoryRoot();string wizard=File.ReadAllText(Path.Combine(root,"01_CORE","src","BARANG.Backoffice","Components","Pages","OrderWizard.razor"));Assert.Contains("Wizard_Header",wizard);Assert.Contains("AdditionalServices",wizard);Assert.Contains("Wizard_Shipping",wizard);Assert.Contains("Wizard_Pricing",wizard);Assert.Contains("Wizard_Review",wizard);string priorityKey=string.Concat("@P[",(char)34,"Priority",(char)34,"]");string legacyPriorityKey=string.Concat("@L[",(char)34,"Priority",(char)34,"]");Assert.Contains(priorityKey,wizard);Assert.DoesNotContain(legacyPriorityKey,wizard);string fa=File.ReadAllText(Path.Combine(root,"01_CORE","src","BARANG.Backoffice","Localization","AppStrings.resx"));string ar=File.ReadAllText(Path.Combine(root,"01_CORE","src","BARANG.Backoffice","Localization","AppStrings.ar.resx"));Assert.Contains("تحویل و ارسال",fa);Assert.Contains("التسليم والشحن",ar);}
    [Fact] public void OrderWizardPersianSurfaceHasNoKnownRawNavigationOrPriorityLabels(){string root=FindRepositoryRoot();string[] files=[Path.Combine(root,"01_CORE","src","BARANG.Backoffice","Components","Pages","OrderWizard.razor"),Path.Combine(root,"01_CORE","src","BARANG.Backoffice","Components","OrderStep4Panel.razor"),Path.Combine(root,"01_CORE","src","BARANG.Backoffice","Components","OrderStep5Panel.razor"),Path.Combine(root,"01_CORE","src","BARANG.Backoffice","Components","OrderStep6Panel.razor"),Path.Combine(root,"01_CORE","src","BARANG.Backoffice","Components","OrderStep7Panel.razor")];string all=string.Join("\n",files.Select(File.ReadAllText));string legacyPriorityKey=string.Concat("@L[",(char)34,"Priority",(char)34,"]");string legacyBackKey=string.Concat("@L[",(char)34,"Back",(char)34,"]");string legacyPricingKey=string.Concat("@L[",(char)34,"PricingFailed",(char)34,"]");Assert.DoesNotContain(legacyPriorityKey,all);Assert.DoesNotContain(legacyBackKey,all);Assert.DoesNotContain(legacyPricingKey,all);}
    private static string FindRepositoryRoot(){DirectoryInfo? current=new(AppContext.BaseDirectory);while(current is not null&&!Directory.Exists(Path.Combine(current.FullName,"01_CORE")))current=current.Parent;return current?.FullName??throw new DirectoryNotFoundException("Repository root not found.");}
}
